using System;using System.Linq;using System.Collections;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;
namespace TriReviewBridge {
 public partial class WorkbenchApp {
  bool CollabMode;object CollabProof,UxLastGovernanceReminder;
  string PlanState(object plan){var state=Json.Str(plan,"state");var names=Json.D("WAITING_OWNER","等待负责人结果","OWNER_UNKNOWN","负责人投递待核对，不重发","PAUSED","已暂停","REVIEW_QUEUED","独立复核已排队","REVIEW_UNKNOWN","复核投递待核对，不重发","REVIEW_APPROVED","本版文字复核通过","CHANGES_REQUESTED","复核要求修改","REJECTED","复核未通过","CANCELLED","已取消","NEEDS_USER","需要你处理");return Json.Str(names,state)==""?state:Json.Str(names,state);}
  string PlanSummary(object plan){return "负责人："+Name(Json.Str(plan,"ownerId"))+"\n独立复核："+Name(Json.Str(plan,"reviewerId"))+"\n状态："+PlanState(plan)+(String.IsNullOrEmpty(Json.Str(plan,"blockReason"))?"":"\n原因："+Json.Str(plan,"blockReason"))+"\n文字复核不代表用户验收或实施授权。";}
  string GovernanceReminderText(object reminder){return "当前请求的治理说明\n请求："+Json.Str(reminder,"request")+"\n规则："+Json.Str(reminder,"rule")+"\n影响："+Json.Str(reminder,"impact")+"\n处理："+Json.Str(reminder,"alternative");}
  void AppendCollaborationContext(System.Collections.Generic.List<string> issues,object item){if(!UxMode)return;var plans=Json.Arr(Json.Get(State,"collaborationPlans"));var related=item==null?null:plans.LastOrDefault(p=>Json.Str(p,"ownerTaskId")==Json.Str(item,"id")||Json.Str(p,"reviewItemId")==Json.Str(item,"id"));if(related==null&&plans.Length==1)related=plans[0];if(related!=null)C<TextBlock>("ContextReviewText").Text+="\n\n本会话协作计划\n"+PlanSummary(related);else if(plans.Length>1)C<TextBlock>("ContextReviewText").Text+="\n\n本会话有 "+plans.Length+" 个协作计划，选中其任务或查询协作进度。";foreach(var plan in plans){var state=Json.Str(plan,"state");if(state=="OWNER_UNKNOWN"||state=="REVIEW_UNKNOWN")issues.Add("协作计划有投递待核对，不自动重发");else if(state=="NEEDS_USER")issues.Add("协作计划需要你处理");else if(state=="PAUSED")issues.Add("协作计划已暂停");}if(UxLastGovernanceReminder!=null){issues.Add("当前请求未通过治理检查");C<TextBlock>("ContextReviewText").Text+="\n\n"+GovernanceReminderText(UxLastGovernanceReminder);}}
  async Task NavigateNewScope(Scope target){await Choose(target);await RefreshNavigation();}
  async Task RunSourceRevisionSelfTest(){await Post("configure","paused",true);var chat=await Post("chat","text","虚构来源材料供原生修订验证","recipients",new string[]{"hermes"});await RefreshWorkspace();var raw=Json.Arr(Json.Get(State,"messages")).Single(m=>Json.Str(m,"case_id")==Json.Str(chat,"id")&&Json.Str(m,"author")=="user");var message=new MessageRow(){Id=Json.Str(raw,"id"),CaseId=Json.Str(raw,"case_id"),Author="user",Body=Json.Str(raw,"body"),Raw=raw};await NewReview(message.Body,null,message);var review=Json.Arr(Json.Get(State,"items")).Single(i=>Json.Str(i,"sourceMessageId")==message.Id&&Json.Str(i,"scope")=="text_only_review");var first=Json.Show(Json.Get(Json.Get(review,"snapshot"),"source_message"));var item=new ItemRow(){Id=Json.Str(review,"id"),Title=Json.Str(review,"title"),Body=Json.Str(review,"body"),Revision=Json.Str(review,"revision"),Raw=review};await NewReview(item.Body+"\n虚构合法修订说明",item);var revised=Json.Arr(Json.Get(State,"items")).Single(i=>Json.Str(i,"id")==item.Id);if(Json.Str(revised,"revision")!="2"||Json.Str(revised,"sourceMessageId")!=message.Id||Json.Show(Json.Get(Json.Get(revised,"snapshot"),"source_message"))!=first)throw new Exception("Native source review revision lost frozen provenance");await Post("cancel","itemId",item.Id);await Post("cancel","itemId",Json.Str(chat,"id"));}
  async Task RunCollaborationSelfTest(){if(!CollabMode)return;var previousScope=CurrentScope;Composer.Text="虚构创建新会话前的未发送草稿";var project=await Client.Call("/api/projects",Json.D("name","虚构组合计划原生自检"));string pid=Json.Str(project,"id");var ws=await Client.Call("/api/projects/"+pid+"/workspaces",Json.D("name","负责人完成后独立复核","participants",new string[]{"hermes","deepseek","chatgpt"}));await NavigateNewScope(new Scope(){ProjectId=pid,ProjectName="虚构组合计划原生自检",WorkspaceId=Json.Str(ws,"id"),WorkspaceName="负责人完成后独立复核"});foreach(string role in new[]{"hermes","deepseek","chatgpt"})await Post("bind-simulation","agentId",role,"title","虚构组合计划 "+role);await Post("configure","paused",false,"recipients",new string[]{"hermes"});ParticipantKey="";await RefreshWorkspace();Composer.Text="让Hermes负责整理虚构颜色说明，DSH复核，ChatGPT不参与";await Send();if(Composer.Text!="")throw new Exception("Native combination request did not execute");await WaitForState(v=>Json.Arr(Json.Get(v,"collaborationPlans")).Any(p=>Json.Str(p,"state")=="REVIEW_APPROVED"),"persistent owner-to-reviewer collaboration");var plan=Json.Arr(Json.Get(State,"collaborationPlans")).Single();if(Json.Bool(plan,"userAuthorized")||Json.Bool(plan,"executionAuthorized"))throw new Exception("Plan outcome became authorization");if(Json.Arr(Json.Get(State,"deliveries")).Any(d=>Json.Str(d,"role")=="chatgpt"))throw new Exception("Excluded third party received plan");if(!C<TextBlock>("ContextReviewText").Text.Contains("协作计划"))throw new Exception("Collaboration context not shown");Composer.Text="查询当前协作计划状态";await Send();if(Composer.Text!="")throw new Exception("Native collaboration status query failed");var planScope=CurrentScope;await Choose(previousScope);if(Composer.Text!="虚构创建新会话前的未发送草稿")throw new Exception("Creating a scope saved draft under the new workspace");await Choose(planScope);await RunSourceRevisionSelfTest();CollabProof=Json.D("passed",true,"scopeCreationPreservesOldDraft",true,"messageReviewLegalRevisionPreservesSource",true,"persistentPlanId",Json.Str(plan,"id"),"ownerThenIndependentReviewer",true,"excludedAgentNotInvited",true,"planStatusQueried",true,"executionAuthorized",false,"realAgentOperations",0);}
 }
}
